script:
(function () {
  'use strict';
  // Long-run wealth: high-deductible plan + invested HSA vs. a traditional plan, yearly steps.
  // Premiums and out-of-pocket costs rise each year by the medical inflation rate (f = (1 + i)^y).
  //   premiums       = 12 x monthly premium x f x (1 - (fed + state + 7.65%) if taken pre-tax)
  //   HSA            = (HSA + your contribution + employer's - bills paid from it) x (1 + r)
  //   HSA plan cost  = premiums + bills paid out of pocket + your contribution x (1 - tax rate)
  //   traditional    = premiums + out-of-pocket costs
  // Whichever plan costs less that year invests the difference (start of year) in a taxable
  // account growing at r x (1 - tax on growth). Wealth: HSA plan = HSA + its taxable account;
  // traditional = its taxable account. Your contribution is capped at the 2026 limit minus the
  // employer's, and held level (the limit itself rises with inflation over time).
  // CHECKS (Node, scratch tests): no medical bills, 0% inflation, equal premiums, $3,000 + $750 a
  // year at 6% for 20 years -> HSA = 3,750 x 1.06 x (1.06^20 - 1) / 0.06 = $146,222.73; the
  // traditional side invests the HSA plan's extra cost 3,000 x (1 - 0.3465) = $1,960.50 a year at
  // 6% x 0.85 = 5.1% -> 1,960.50 x 1.051 x (1.051^20 - 1) / 0.051 = $68,856.44; 0% return -> sums
  // of contributions; defaults year 1: HSA plan 1,800 x 0.6535 + 2,500 + 1,960.50 = $5,636.80,
  // traditional 4,200 x 0.6535 + 1,000 = $3,744.70; contribution $5,000 + $750 employer on
  // self-only is capped at $3,650; bills larger than the HSA are paid from pocket.
  // ---- 2026 HSA LIMITS (calendar year 2026) ---------------------------------------------------
  // Source: IRS Rev. Proc. 2025-19 (IRC 223 inflation adjustments for 2026), repeated in IRS
  // Pub. 969 and Pub. 15-B (2026). Catch-up: IRC 223(b)(3)(B), a fixed $1,000 at 55 or older.
  // FICA: 6.2% Social Security + 1.45% Medicare employee rates (IRC 3101).
  var HSA = { year: 2026, limit: { self: 4400, family: 8750 }, catchUp55: 1000 };
  var FICA_RATE = 0.0765;
  // --------------------------------------------------------------------------------------------

  // p: premH, oopH, premT, oopT, balance, contrib, employer, limit, payFromHsa, years, ret,
  // inflation, drag, hsaRate, premRate (rates as decimals)
  function compare(p) {
    var er = Math.min(p.employer, p.limit), you = Math.min(p.contrib, Math.max(0, p.limit - er));
    var rAfter = p.ret * (1 - p.drag), bal = p.balance, sideH = 0, sideT = 0, rows = [], short = 0, gap = 0;
    for (var y = 0; y < p.years; y++) {
      var f = Math.pow(1 + p.inflation, y);
      var premH = p.premH * 12 * f * (1 - p.premRate), premT = p.premT * 12 * f * (1 - p.premRate);
      var billH = p.oopH * f, billT = p.oopT * f;
      bal += you + er;
      var fromHsa = p.payFromHsa ? Math.min(billH, bal) : 0;
      if (p.payFromHsa) short += billH - fromHsa;
      bal -= fromHsa;
      var costH = premH + (billH - fromHsa) + you * (1 - p.hsaRate), costT = premT + billT;
      var diff = costT - costH;
      if (diff > 0) sideH += diff; else sideT -= diff;
      gap += diff;
      bal *= 1 + p.ret; sideH *= 1 + rAfter; sideT *= 1 + rAfter;
      rows.push({ year: y + 1, costH: costH, costT: costT, bal: bal, wealthH: bal + sideH, wealthT: sideT });
    }
    return { rows: rows, bal: bal, sideH: sideH, sideT: sideT, wealthH: bal + sideH, wealthT: sideT, you: you, er: er,
             capped: p.contrib > you + 0.005 || p.employer > p.limit + 0.005, short: short, gap: gap,
             first: rows[0], taxSaved: you * p.hsaRate };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function signed(x) { return Math.abs(x) < 0.5 ? money(0) : (x < 0 ? '−' + money(-x) : money(x)); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var premH = num('htPremH'), oopH = num('htOopH'), premT = num('htPremT'), oopT = num('htOopT'),
        balance = num('htBalance'), contrib = num('htContrib'), employer = num('htEmployer'),
        years = num('htYears'), ret = num('htReturn'), fed = parseFloat(document.getElementById('htFed').value),
        state = num('htState'), inflation = num('htInflation'), drag = num('htDrag');
    var coverage = document.getElementById('htCoverage').value === 'family' ? 'family' : 'self';
    var age55 = document.getElementById('htAge55').checked, payroll = document.getElementById('htPayroll').checked,
        preTax = document.getElementById('htPreTaxPrem').checked,
        payFromHsa = document.getElementById('htPayFrom').value === 'hsa';
    var error = document.getElementById('htError'), msg = '';
    if ([premH, oopH, premT, oopT, balance, contrib, employer, years, ret, fed, state, inflation, drag].some(isNaN) ||
        [premH, oopH, premT, oopT, balance, contrib, employer].some(function (v) { return v < 0; }))
      msg = 'Enter non-negative amounts in every field.';
    else if (years < 1 || years > 40 || Math.round(years) !== years) msg = 'Enter a whole number of years from 1 to 40.';
    else if (ret < 0 || ret > 20) msg = 'Enter an investment return from 0 to 20%.';
    else if (state < 0 || state > 15) msg = 'Enter a state tax rate from 0 to 15%.';
    else if (inflation < 0 || inflation > 20) msg = 'Enter a medical cost increase from 0 to 20%.';
    else if (drag < 0 || drag > 50) msg = 'Enter a tax on taxable-account growth from 0 to 50%.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }

    var payrollRate = fed / 100 + state / 100 + FICA_RATE, incomeRate = fed / 100 + state / 100;
    var r = compare({ premH: premH, oopH: oopH, premT: premT, oopT: oopT, balance: balance, contrib: contrib,
      employer: employer, limit: HSA.limit[coverage] + (age55 ? HSA.catchUp55 : 0), payFromHsa: payFromHsa,
      years: years, ret: ret / 100, inflation: inflation / 100, drag: drag / 100,
      hsaRate: payroll ? payrollRate : incomeRate, premRate: preTax ? (payroll ? payrollRate : incomeRate) : 0 });
    var adv = r.wealthH - r.wealthT;
    set('htAdvLabel', adv >= 0 ? 'HSA plan comes out ahead by' : 'Traditional plan comes out ahead by');
    set('htAdv', money(Math.abs(adv)));
    set('htWealthH', money(r.wealthH));
    set('htWealthT', money(r.wealthT));
    set('htBal', money(r.bal));
    set('htSideH', money(r.sideH));
    set('htNonMed', money(r.bal * (1 - incomeRate)));
    set('htCostH', money(r.first.costH));
    set('htCostT', money(r.first.costT));
    set('htTaxSaved', money(r.taxSaved));
    set('htSummary', 'After ' + years + ' years the high-deductible plan costs you ' + money(Math.abs(r.gap)) +
        (r.gap >= 0 ? ' less' : ' more') + ' in total than the traditional plan (counting your HSA contributions as a cost), ' +
        'and its HSA holds ' + money(r.bal) + ' that can pay medical bills tax-free at any age.');
    var capEl = document.getElementById('htCapped');
    capEl.hidden = !r.capped;
    if (r.capped) capEl.textContent = 'Contributions are capped at the ' + HSA.year + ' limit of ' +
        money(HSA.limit[coverage] + (age55 ? HSA.catchUp55 : 0)) + ' for your coverage, so you put in ' + money(r.you) +
        ' a year and your employer ' + money(r.er) + '.';
    var shortEl = document.getElementById('htShort');
    shortEl.hidden = !(r.short > 0.5);
    if (r.short > 0.5) shortEl.textContent = 'In some years the HSA could not cover all the bills, so ' + money(r.short) +
        ' in total was paid out of pocket instead.';
    var body = document.getElementById('htSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.year, money(row.costH), money(row.costT), money(row.bal), money(row.wealthH), money(row.wealthT), signed(row.wealthH - row.wealthT)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('htForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
